async function callWithBreaker<T>(fn: () => Promise<T>, breaker: Breaker): Promise<T> {
  if (breaker.isOpen()) throw new Error('circuit open: failing fast');
  try {
    const result = await withTimeout(fn(), 500);
    breaker.recordSuccess();
    return result;
  } catch (err) {
    breaker.recordFailure(); // opens after N failures within window
    throw err;
  }
}

async function getOrderView(orderId: string): Promise<OrderView> {
  const order = await ordersApi.get(orderId);
  const [customer, payments] = await Promise.all([
    customersApi.get(order.customerId),
    paymentsApi.listByOrder(orderId),
  ]);
  return { ...order, customer, payments };
}

async function retryIdempotent<T>(fn: () => Promise<T>, tries = 4): Promise<T> {
  for (let attempt = 0; ; attempt++) {
    try { return await fn(); } catch (err) {
      if (attempt >= tries - 1) throw err;
      await sleep(Math.random() * Math.min(100 * 2 ** attempt, 5000)); // full jitter
    }
  }
}

async function handle(event: Event) {
  await db.transaction(async (tx) => {
    if (await tx.processed.exists(event.id)) return; // duplicate redelivery
    await applyBusinessChange(tx, event);
    await tx.processed.insert({ id: event.id });
  });
}
